import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import bannerImg from "../assets/banner.png";

export default function HomePage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [activeNav, setActiveNav] = useState("inicio");

  const firstName = user?.displayName
    ? user.displayName.split(" ")[0]
    : user?.email
    ? user.email.split("@")[0]
    : "Usuario";

  const detections = [
    {
      title: "Sigatoka Negra",
      level: "Alto",
      time: "2h ago",
      badge: "bg-red-50 text-red-600 border-red-200",
      dot: "bg-red-500",
      image: "https://images.unsplash.com/photo-1524593166156-312f362cada0?q=80&w=400&auto=format&fit=crop",
    },
    {
      title: "Mancha Foliar",
      level: "Medio",
      time: "Jul 2, 2024",
      badge: "bg-amber-50 text-amber-700 border-amber-200",
      dot: "bg-amber-500",
      image: "https://images.unsplash.com/photo-1501004318641-b39e6451bec6?q=80&w=400&auto=format&fit=crop",
    },
    {
      title: "Hoja Sana",
      level: "Sano",
      time: "Jun 15, 2024",
      badge: "bg-green-50 text-green-700 border-green-200",
      dot: "bg-green-500",
      image: "https://images.unsplash.com/photo-1471193945509-9ad0617afabf?q=80&w=400&auto=format&fit=crop",
    },
    {
      title: "Sigatoka Amarilla",
      level: "Medio",
      time: "Jun 10, 2024",
      badge: "bg-amber-50 text-amber-700 border-amber-200",
      dot: "bg-amber-500",
      image: "https://images.unsplash.com/photo-1466692476868-aef1dfb1e735?q=80&w=400&auto=format&fit=crop",
    },
  ];

  const navItems = [
    { key: "inicio", label: "Inicio", icon: "🏠" },
    { key: "escaneos", label: "Escaneos", icon: "📷" },
    { key: "historial", label: "Historial", icon: "🕒" },
    { key: "enfermedades", label: "Enfermedades", icon: "🍃" },
    { key: "recomendaciones", label: "Recomendaciones", icon: "📋" },
    { key: "ajustes", label: "Ajustes", icon: "⚙️" },
  ];

  return (
    <div className="min-h-screen bg-[#f4f7f1] text-gray-800">

      {/* NAVBAR — solo logo + usuario, sin links duplicados */}
      <header className="bg-white border-b border-gray-200 px-4 sm:px-6 lg:px-8 py-3 flex items-center justify-between shadow-sm sticky top-0 z-20">
        <div className="flex items-center gap-2.5">
          <div className="w-10 h-10 rounded-xl bg-green-700 flex items-center justify-center text-white text-lg shrink-0">
            🌿
          </div>
          <div className="hidden sm:block">
            <h1 className="font-bold text-base leading-tight">Detección Sigatoka</h1>
            <p className="text-xs text-gray-500">Sistema Inteligente Agrícola</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button className="w-10 h-10 rounded-full bg-gray-100 flex items-center justify-center text-base relative shrink-0">
            🔔
            <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full" />
          </button>

          <div className="flex items-center gap-2.5">
            <UserAvatar user={user} firstName={firstName} />
            <div className="hidden sm:block">
              <p className="text-xs text-gray-500 leading-none">Hola,</p>
              <h2 className="font-semibold text-sm leading-tight">{firstName} 👋</h2>
            </div>
          </div>
        </div>
      </header>

      <div className="flex">

        {/* SIDEBAR — único menú, solo desktop */}
        <aside className="hidden lg:flex flex-col w-60 shrink-0 bg-white border-r border-gray-100 p-4 min-h-[calc(100vh-64px)]">
          <nav className="space-y-1">
            {navItems.map((item) => (
              <button
                key={item.key}
                onClick={() => setActiveNav(item.key)}
                className={`w-full flex items-center gap-3 text-left px-3.5 py-2.5 rounded-xl transition text-sm ${
                  activeNav === item.key
                    ? "bg-green-50 text-green-700 font-semibold"
                    : "hover:bg-gray-50 text-gray-600"
                }`}
              >
                <span className="text-base">{item.icon}</span>
                {item.label}
              </button>
            ))}
          </nav>

          <div className="bg-green-50 rounded-2xl p-4 mt-auto">
            <h3 className="font-semibold text-sm mb-1">¿Necesitas ayuda?</h3>
            <p className="text-xs text-gray-600 mb-3">
              Consulta nuestras guías y recomendaciones.
            </p>
            <button className="w-full bg-green-700 hover:bg-green-800 transition text-white py-2 rounded-xl text-sm font-medium">
              Ver guías
            </button>
          </div>
        </aside>

        {/* CONTENT */}
        <main className="flex-1 p-4 sm:p-6 lg:p-8 space-y-5 max-w-[1400px] mx-auto w-full">

          {/* HERO + STATS */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">

            <div className="lg:col-span-2 relative overflow-hidden rounded-3xl bg-gradient-to-br from-[#0d3d17] via-[#155726] to-[#1f6e34] min-h-[220px] sm:min-h-[260px] p-6 sm:p-8 flex flex-col justify-center">
              <img
                src={bannerImg}
                alt="cultivos"
                className="absolute right-0 top-0 h-full w-1/2 sm:w-2/5 object-cover opacity-50"
              />
              <div className="absolute inset-0 bg-gradient-to-r from-[#0d3d17] via-[#0d3d17]/70 to-transparent" />

              <div className="relative z-10 max-w-md">
                <span className="inline-block bg-white/15 border border-white/20 px-3 py-1.5 rounded-full text-white text-xs font-medium mb-4">
                  🌱 Detección inteligente
                </span>
                <h1 className="text-2xl sm:text-3xl lg:text-4xl font-bold leading-tight text-white mb-3">
                  Protege tus cultivos,
                  <span className="text-lime-300"> asegura tu futuro</span>
                </h1>
                <p className="text-sm sm:text-base text-green-100">
                  Detecta enfermedades de Sigatoka negra con IA en segundos.
                </p>
              </div>
            </div>

            <div className="grid grid-cols-3 lg:grid-cols-1 gap-3">
              <StatCard icon="📈" value="12" label="Escaneos" color="green" />
              <StatCard icon="🛡️" value="3" label="Enfermedades" color="blue" />
              <StatCard icon="⚠️" value="2" label="Alto riesgo" color="red" />
            </div>
          </div>

          {/* SCAN CARD */}
          <button
            onClick={() => navigate("/scan")}
            className="w-full bg-white border-2 border-dashed border-green-200 rounded-3xl p-5 sm:p-6 flex items-center gap-4 sm:gap-6 hover:bg-green-50/40 hover:border-green-300 transition"
          >
            <div className="w-14 h-14 sm:w-16 sm:h-16 rounded-2xl bg-green-100 flex items-center justify-center text-2xl sm:text-3xl shrink-0">
              🌿
            </div>
            <div className="text-left flex-1">
              <h2 className="text-lg sm:text-xl font-bold mb-0.5">Escanear planta</h2>
              <p className="text-gray-500 text-sm">
                Toma o sube una foto para detectar enfermedades de Sigatoka.
              </p>
            </div>
            <div className="w-11 h-11 rounded-full bg-green-700 text-white text-xl flex items-center justify-center shrink-0">
              →
            </div>
          </button>

          {/* DETECCIONES RECIENTES — rediseñadas */}
          <div>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg sm:text-xl font-bold">Detecciones recientes</h2>
              <button
                onClick={() => navigate("/history")}
                className="text-green-700 text-sm font-medium hover:underline shrink-0"
              >
                Ver todo →
              </button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-2 xl:grid-cols-4 gap-3">
              {detections.map((item, index) => (
                <button
                  key={index}
                  onClick={() => navigate(`/result/${index + 1}`)}
                  className="bg-white rounded-2xl border border-gray-100 overflow-hidden hover:shadow-md transition text-left group"
                >
                  <div className="relative h-28 overflow-hidden">
                    <img
                      src={item.image}
                      alt={item.title}
                      className="w-full h-full object-cover group-hover:scale-105 transition duration-300"
                    />
                    <span className={`absolute top-2 right-2 text-xs font-semibold px-2.5 py-1 rounded-full border ${item.badge}`}>
                      {item.level}
                    </span>
                  </div>
                  <div className="p-3.5">
                    <div className="flex items-center gap-1.5 mb-0.5">
                      <span className={`w-1.5 h-1.5 rounded-full ${item.dot}`} />
                      <h3 className="font-semibold text-sm truncate">{item.title}</h3>
                    </div>
                    <p className="text-xs text-gray-500">Banano · {item.time}</p>
                  </div>
                </button>
              ))}
            </div>
          </div>

          {/* ALERTA */}
          <div className="bg-amber-50 border border-amber-200 rounded-3xl p-5 sm:p-6 flex flex-col sm:flex-row sm:items-center gap-4">
            <div className="flex items-center gap-4 flex-1">
              <div className="w-12 h-12 rounded-2xl bg-amber-100 flex items-center justify-center text-xl shrink-0">
                💡
              </div>
              <div>
                <h3 className="font-semibold text-sm sm:text-base text-amber-900">
                  La detección temprana puede salvar tus cultivos
                </h3>
                <p className="text-amber-700 text-xs sm:text-sm">
                  Escanea tus plantas regularmente para un mejor control.
                </p>
              </div>
            </div>
            <button
              onClick={() => navigate("/recomendaciones")}
              className="bg-white hover:bg-amber-100 transition text-amber-700 border border-amber-200 px-5 py-2.5 rounded-xl text-sm font-semibold whitespace-nowrap shrink-0"
            >
              Ver recomendaciones
            </button>
          </div>

        </main>
      </div>

      {/* BOTTOM NAV — solo móvil/tablet */}
      <div className="lg:hidden sticky bottom-0 bg-white border-t border-gray-200 px-4 py-2 z-20">
        <div className="flex items-center justify-around">
          {[
            { key: "inicio", label: "Inicio", icon: "🏠" },
            { key: "escaneos", label: "Scan", icon: "📷" },
            { key: "historial", label: "Historial", icon: "🕒" },
            { key: "ajustes", label: "Perfil", icon: "👤" },
          ].map((item) => (
            <button
              key={item.key}
              onClick={() => {
                setActiveNav(item.key);
                if (item.key === "escaneos") navigate("/scan");
                if (item.key === "ajustes") navigate("/profile");
              }}
              className={`flex flex-col items-center gap-0.5 px-4 py-1.5 rounded-xl transition ${
                activeNav === item.key ? "text-green-700" : "text-gray-400"
              }`}
            >
              <span className="text-lg">{item.icon}</span>
              <span className="text-[11px] font-medium">{item.label}</span>
            </button>
          ))}
        </div>
      </div>

    </div>
  );
}

function StatCard({ icon, value, label, color }) {
  const colors = {
    green: { bg: "bg-green-50", text: "text-green-600" },
    blue: { bg: "bg-blue-50", text: "text-blue-600" },
    red: { bg: "bg-red-50", text: "text-red-500" },
  };
  const c = colors[color];

  return (
    <div className="bg-white rounded-2xl p-3 lg:p-5 border border-gray-100 flex lg:flex-col items-center lg:items-start gap-2 lg:gap-0">
      <div className={`w-10 h-10 lg:w-12 lg:h-12 rounded-xl ${c.bg} flex items-center justify-center text-lg lg:text-xl shrink-0 lg:mb-3`}>
        {icon}
      </div>
      <div className="flex lg:flex-col items-baseline lg:items-start gap-1.5 lg:gap-0">
        <span className={`font-bold text-xl lg:text-2xl ${c.text}`}>{value}</span>
        <p className="text-gray-500 text-xs lg:text-sm">{label}</p>
      </div>
    </div>
  );
}

function UserAvatar({ user, firstName }) {
  const [imgError, setImgError] = useState(false);

  if (user?.photoURL && !imgError) {
    return (
      <img
        src={user.photoURL}
        alt="profile"
        referrerPolicy="no-referrer"
        onError={() => setImgError(true)}
        className="w-9 h-9 rounded-full object-cover shrink-0"
      />
    );
  }

  return (
    <div className="w-9 h-9 rounded-full bg-green-700 flex items-center justify-center text-white text-sm font-medium shrink-0">
      {firstName[0].toUpperCase()}
    </div>
  );
}
